import { TANK_VIEWER } from './tank-viewer';

export interface ViewerRejection {
  id: string;
  message: string;
}
/** _-2c.CreateEffect/Run: independent MovieClip lifetimes, removed at their final frame. */
export class ViewerRejections {
  private serial = 0;
  private snapshot: readonly ViewerRejection[] = [];
  private frames = new Map<string, number>();
  private listeners = new Set<() => void>();
  getSnapshot = () => this.snapshot;
  subscribe = (listener: () => void) => {
    this.listeners.add(listener);
    return () => {
      this.listeners.delete(listener);
    };
  };
  add(message: string) {
    const id = `rejection:${++this.serial}`;
    this.frames.set(id, 1);
    this.snapshot = [...this.snapshot, { id, message }];
    this.changed();
    return id;
  }
  frame(id: string) {
    return this.frames.get(id);
  }
  step() {
    let removed = false;
    for (const [id, frame] of this.frames) {
      if (frame + 1 >= TANK_VIEWER.rejection.frameCount) {
        this.frames.delete(id);
        removed = true;
      } else this.frames.set(id, frame + 1);
    }
    if (removed) {
      this.snapshot = this.snapshot.filter((entry) => this.frames.has(entry.id));
      this.changed();
    }
  }
  private changed() {
    for (const listener of this.listeners) listener();
  }
}
import { expect, test } from 'bun:test';
import { ViewerRejections } from '../src/game/core/viewer-rejections';
import { TANK_VIEWER } from '../src/game/core/tank-viewer';

test('rejection metadata retains the authored91-frame independent alpha tracks and source placement', () => {
  const art = TANK_VIEWER.rejection;
  expect([art.symbol, art.x, art.y, art.frameCount]).toEqual([1557, 224, 196, 91]);
  expect(art.frames[59]).toEqual([1, 1, 1]);
  expect(art.frames[60]).toEqual([1, 0.96875, 0.96875]);
  expect(art.frames[69]).toEqual([1, 0.67578125, 0.67578125]);
  expect(art.frames[70]).toEqual([0.953125, 0.64453125, 0.64453125]);
  expect(art.frames[89]).toEqual([0.046875, 0.03125, 0.03125]);
  expect(art.frames[90]).toEqual([0, 0, 0]);
  expect(art.fields[0]).toMatchObject({
    name: 'txtErrorOutputText_txt',
    size: 20,
    wordWrap: true,
    align: 2,
  });
});
test('rejection stays on the authored final visible frame and is deleted when it reaches the end', () => {
  const model = new ViewerRejections(),
    id = model.add('Exceeds your Class');
  const initial = model.getSnapshot();
  expect(model.frame(id)).toBe(1);
  for (let i = 0; i < 89; i++) model.step();
  expect(model.frame(id)).toBe(90);
  expect(model.getSnapshot()).toBe(initial);
  model.step();
  expect(model.frame(id)).toBeUndefined();
  expect(model.getSnapshot()).toEqual([]);
});
test('repeated rejections retain separate messages, clocks and stable lifetime snapshots', () => {
  const model = new ViewerRejections();
  let changes = 0;
  const unsubscribe = model.subscribe(() => changes++);
  const first = model.add('first');
  for (let i = 0; i < 20; i++) model.step();
  const second = model.add('second');
  for (let i = 0; i < 69; i++) model.step();
  expect([model.frame(first), model.frame(second), changes]).toEqual([90, 70, 2]);
  model.step();
  expect(model.getSnapshot()).toEqual([{ id: second, message: 'second' }]);
  expect(model.frame(second)).toBe(71);
  for (let i = 0; i < 20; i++) model.step();
  expect(model.getSnapshot()).toEqual([]);
  expect(changes).toBe(4);
  unsubscribe();
  expect(model.add('third')).not.toBe(first);
  expect(changes).toBe(4);
});
'use client';
import { useCallback, useEffect, useLayoutEffect, useRef, useSyncExternalStore } from 'react';
import type { AssetPack } from '@/game/assets/asset-pack';
import type { StageRuntime } from '@/game/services/stage-runtime';
import { TANK_VIEWER } from '@/game/core/tank-viewer';
import type { ViewerRejections } from '@/game/core/viewer-rejections';
import { CreatorPrimitives, CreatorRasterArt } from './creator-controls';
import { CreatorText } from './creator-text';
import { ViewerGroup } from './tank-viewer-art';

/** Authored1557: timed pointer shield, independent backdrop/title/field fades, no modal dismissal. */
export function ViewerRejectionEffects({
  pack,
  stage,
  model,
}: {
  pack: AssetPack;
  stage: StageRuntime;
  model: ViewerRejections;
}) {
  const effects = useSyncExternalStore(model.subscribe, model.getSnapshot, model.getSnapshot),
    roots = useRef(new Map<string, HTMLDivElement>()),
    layers = useRef(new Map<string, Map<number, HTMLDivElement>>());
  const paint = useCallback(() => {
    for (const [id, root] of roots.current) {
      const frame = model.frame(id);
      root.style.display = frame === undefined ? 'none' : '';
      if (frame === undefined) continue;
      root.dataset.rejectionFrame = String(frame);
      for (const [index, node] of layers.current.get(id) ?? []) {
        const alpha = TANK_VIEWER.rejection.frames[frame - 1][index];
        node.style.opacity = String(alpha);
        node.dataset.rejectionAlpha = String(alpha);
      }
    }
  }, [model]);
  useLayoutEffect(paint, [effects, paint]);
  useEffect(
    () =>
      stage.subscribe({
        step: () => {
          model.step();
          paint();
        },
      }),
    [model, stage, paint],
  );
  function layer(id: string, index: number, node: HTMLDivElement | null) {
    let entries = layers.current.get(id);
    if (node) {
      if (!entries) layers.current.set(id, (entries = new Map()));
      entries.set(index, node);
    } else {
      entries?.delete(index);
      if (!entries?.size) layers.current.delete(id);
    }
  }
  const art = TANK_VIEWER.rejection;
  return (
    <div className="viewer-rejections">
      {effects.map((effect) => (
        <div
          key={effect.id}
          className="viewer-rejection"
          role="status"
          aria-label={`You Cannot Select This Tank: ${effect.message}`}
          ref={(node) => {
            if (node) roots.current.set(effect.id, node);
            else roots.current.delete(effect.id);
          }}
        >
          <div aria-hidden="true">
            <ViewerGroup matrix={{ a: 1, b: 0, c: 0, d: 1, tx: art.x * 20, ty: art.y * 20 }}>
              {art.pieces.map((piece) => {
                const raster = pack.creatorFrames.get(`viewer:rejection:${piece.symbol}`);
                return (
                  <div
                    className="viewer-group"
                    key={piece.symbol}
                    data-rejection-layer={piece.symbol}
                    ref={(node) => layer(effect.id, piece.index, node)}
                  >
                    <ViewerGroup matrix={piece.matrix}>
                      {raster ? (
                        <CreatorRasterArt raster={raster} />
                      ) : (
                        <svg className="viewer-art" width={1} height={1}>
                          <CreatorPrimitives pieces={piece.art} />
                        </svg>
                      )}
                    </ViewerGroup>
                  </div>
                );
              })}
              <div
                className="viewer-group"
                data-rejection-layer="message"
                ref={(node) => layer(effect.id, art.fieldIndex, node)}
              >
                {art.fields.map((field) => (
                  <ViewerGroup key={field.name} matrix={field.matrix}>
                    <CreatorText pack={pack} field={field} text={effect.message} />
                  </ViewerGroup>
                ))}
              </div>
            </ViewerGroup>
          </div>
        </div>
      ))}
    </div>
  );
}
